
:root {
  --black:#080808;
  --gold:#c89a22;
  --gold2:#e1b84a;
  --ink:#171717;
  --muted:#6f6f6f;
  --line:#e8e1d2;
  --paper:#fbfbf9;
  --white:#fff;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,Arial,Helvetica,sans-serif}
a{color:inherit;text-decoration:none}
button{font:inherit}
.nav{position:sticky;top:0;z-index:20;background:rgba(255,255,255,.92);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
.nav-inner{max-width:1180px;margin:auto;padding:14px 22px;display:flex;align-items:center;justify-content:space-between;gap:18px}
.brand{display:flex;align-items:center;gap:10px;font-weight:950;letter-spacing:2px}
.brand-mark{font-size:26px;font-weight:1000;line-height:1}
.brand-mark b{color:var(--gold)}
.navlinks{display:flex;gap:22px;font-size:11px;font-weight:900;letter-spacing:1.2px}
.navlinks a:hover{color:var(--gold)}
.nav-cta{border:1px solid var(--gold);padding:10px 15px;border-radius:7px;font-size:10px;font-weight:950;background:#fff}
.hero{min-height:calc(100vh - 62px);display:grid;place-items:center;overflow:hidden;position:relative}
.hero-bg{position:absolute;inset:0;background-image:linear-gradient(90deg,rgba(255,255,255,.96) 0%,rgba(255,255,255,.86) 43%,rgba(255,255,255,.15) 72%,rgba(255,255,255,.02) 100%),url("data:image/png;base64,");background-size:cover;background-position:center;filter:saturate(.92)}
.hero-content{position:relative;z-index:2;max-width:1180px;width:100%;padding:80px 22px 70px}
.eyebrow{font-size:11px;letter-spacing:5px;font-weight:900;margin-bottom:20px}
.hero h1{font-size:clamp(46px,7vw,92px);line-height:.9;letter-spacing:-4px;margin:0;max-width:650px;font-weight:1000}
.hero h1 span{color:var(--gold)}
.hero p{max-width:560px;font-size:16px;line-height:1.65;color:#555;margin:26px 0}
.buttons{display:flex;flex-wrap:wrap;gap:10px}
.btn{display:inline-flex;align-items:center;justify-content:center;border-radius:7px;padding:14px 19px;font-size:10px;font-weight:950;letter-spacing:1.2px;cursor:pointer}
.btn.gold{background:var(--gold);color:#fff;border:1px solid var(--gold)}
.btn.dark{background:var(--black);color:#fff;border:1px solid var(--black)}
.btn.light{background:#fff;border:1px solid #d7d0c0}
.stats{max-width:1180px;margin:-20px auto 0;padding:0 22px;position:relative;z-index:3}
.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border:1px solid var(--line);box-shadow:0 18px 50px rgba(0,0,0,.08)}
.stat{padding:24px;border-right:1px solid var(--line);text-align:center}
.stat:last-child{border-right:0}
.stat strong{display:block;font-size:28px}
.stat span{display:block;margin-top:5px;font-size:9px;letter-spacing:2px;color:#777;font-weight:900}
.section{max-width:1180px;margin:0 auto;padding:100px 22px}
.section-head{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:35px}
.section-head .eyebrow{color:var(--gold);margin:0 0 8px}
.section h2{font-size:clamp(32px,5vw,54px);line-height:1;margin:0;letter-spacing:-2px}
.section-head p{max-width:470px;color:#666;line-height:1.6}
.features{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.feature{padding:34px 24px;border-right:1px solid var(--line)}
.feature:last-child{border-right:0}
.icon{font-size:27px;margin-bottom:18px}
.feature h3{font-size:14px;letter-spacing:1px;margin:0 0 10px}
.feature p{font-size:12px;line-height:1.65;color:#6b6b6b;margin:0}
.preview{display:grid;grid-template-columns:1.1fr .9fr;gap:20px}
.card{background:#fff;border:1px solid var(--line);padding:28px}
.rank-row{display:grid;grid-template-columns:40px 1fr 100px;gap:10px;align-items:center;padding:14px 0;border-bottom:1px solid #eee}
.rank-row:last-child{border-bottom:0}
.rank-num{font-weight:1000;color:var(--gold)}
.team{display:flex;align-items:center;gap:10px;font-weight:900}
.team-logo{width:34px;height:34px;border:1px solid var(--line);border-radius:7px;display:grid;place-items:center;font-size:11px;background:#fafafa}
.points{text-align:right;font-weight:1000}
.kpi{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:15px}
.kpi-box{padding:18px;background:#faf9f4;border:1px solid var(--line)}
.kpi-box small{display:block;font-size:8px;color:#777;letter-spacing:1.3px;font-weight:900}
.kpi-box strong{font-size:22px;display:block;margin-top:5px}
.cta{background:var(--black);color:#fff;position:relative;overflow:hidden}
.cta:after{content:"";position:absolute;width:380px;height:380px;border:1px solid rgba(200,154,34,.35);border-radius:50%;right:-130px;top:-160px}
.cta-inner{max-width:1180px;margin:auto;padding:80px 22px;position:relative;z-index:2}
.cta h2{font-size:clamp(38px,6vw,70px);line-height:.95;margin:0 0 20px;max-width:720px;letter-spacing:-3px}
.cta h2 span{color:var(--gold2)}
.cta p{color:#bdbdbd;max-width:600px;line-height:1.6}
.footer{padding:30px 22px;background:#050505;color:#aaa;text-align:center;font-size:10px;letter-spacing:1px}
.footer b{color:#fff}
.modal{position:fixed;inset:0;background:rgba(0,0,0,.72);display:none;place-items:center;z-index:50;padding:20px}
.modal.open{display:grid}
.modal-box{background:#fff;max-width:520px;width:100%;padding:30px;border-radius:12px;position:relative}
.modal-box h3{margin:0 0 10px;font-size:24px}
.modal-box p{color:#666;line-height:1.5;font-size:13px}
.close{position:absolute;right:15px;top:15px;border:0;background:#f2f2f2;border-radius:50%;width:32px;height:32px;cursor:pointer}
@media(max-width:900px){
 .navlinks{display:none}
 .hero{min-height:720px}
 .hero-bg{background-position:62% center}
 .hero-content{padding-top:60px}
 .stat-grid,.features{grid-template-columns:repeat(2,1fr)}
 .stat:nth-child(2){border-right:0}
 .stat:nth-child(-n+2){border-bottom:1px solid var(--line)}
 .preview{grid-template-columns:1fr}
}
@media(max-width:560px){
 .hero h1{letter-spacing:-2px}
 .hero-bg{background-image:linear-gradient(90deg,rgba(255,255,255,.97) 0%,rgba(255,255,255,.9) 58%,rgba(255,255,255,.3) 100%),url("data:image/png;base64,")}
 .stat-grid,.features{grid-template-columns:1fr}
 .stat{border-right:0;border-bottom:1px solid var(--line)}
 .stat:last-child{border-bottom:0}
 .section{padding:70px 18px}
 .nav-inner{padding:12px 16px}
}

