.sqi-welcome-inner{width:min(90vw,560px);padding:30px}
.sqi-welcome-logo{width:min(64vw,330px);height:auto;display:block;margin:0 auto 28px;filter:drop-shadow(0 0 22px rgba(200,154,34,.16))}
.sqi-welcome-kicker{font-size:9px;letter-spacing:4px;color:#c89a22;font-weight:950}
.sqi-welcome-title{font-size:clamp(28px,7vw,56px);font-weight:950;letter-spacing:-1.8px;margin:10px 0}
.sqi-welcome-text{font-size:11px;color:#8b8b8b;letter-spacing:.6px}
.sqi-welcome-line{height:1px;width:min(260px,60vw);background:#c89a22;margin:22px auto 0;box-shadow:0 0 14px rgba(200,154,34,.45)}


#sqiDarkLoader{position:fixed;inset:0;z-index:999999;background:#020203;display:flex;align-items:center;justify-content:center;overflow:hidden;transition:opacity .8s ease,visibility .8s ease}
#sqiDarkLoader.hide{opacity:0;visibility:hidden;pointer-events:none}
.sqi-loader-noise{position:absolute;inset:-50%;opacity:.08;background-image:radial-gradient(#fff 1px,transparent 1px);background-size:5px 5px;animation:sqiNoise .15s steps(2) infinite}
.sqi-loader-vignette{position:absolute;inset:0;background:radial-gradient(circle at center,transparent 0 22%,rgba(0,0,0,.45) 58%,#000 100%)}
.sqi-loader-lines{position:absolute;inset:0;background:linear-gradient(90deg,transparent 0 49.7%,rgba(200,154,34,.08) 50%,transparent 50.3%),linear-gradient(0deg,transparent 0 49.7%,rgba(200,154,34,.05) 50%,transparent 50.3%);opacity:.35}
.sqi-loader-core{position:relative;text-align:center;color:#fff;transform:scale(.94);animation:sqiCore 1.2s cubic-bezier(.2,.8,.2,1) forwards}
.sqi-loader-mark{font:950 clamp(82px,23vw,210px)/.78 Arial,sans-serif;letter-spacing:-.11em;text-shadow:0 0 12px rgba(255,255,255,.12),0 0 35px rgba(200,154,34,.18);filter:drop-shadow(0 0 18px rgba(200,154,34,.12))}
.sqi-loader-mark b{color:#c89a22}
.sqi-loader-kicker{margin-top:25px;font:900 10px/1 Arial,sans-serif;letter-spacing:6px;color:#aaa}
.sqi-loader-line{width:min(260px,62vw);height:2px;background:#171719;margin:28px auto 0;overflow:hidden;position:relative}
.sqi-loader-line:after{content:"";position:absolute;left:-55%;top:0;width:55%;height:100%;background:#c89a22;box-shadow:0 0 16px #c89a22;animation:sqiLoad 1.55s cubic-bezier(.4,0,.2,1) infinite}
.sqi-loader-status{margin-top:14px;font:800 8px/1 Arial,sans-serif;letter-spacing:3px;color:#555}
.sqi-loader-flash{position:absolute;inset:0;background:#fff;opacity:0;pointer-events:none;animation:sqiFlash 1.65s ease-out .55s}
@keyframes sqiCore{0%{opacity:0;transform:scale(1.18);filter:blur(14px)}45%{opacity:1;transform:scale(.97);filter:blur(0)}100%{opacity:1;transform:scale(1)}}
@keyframes sqiLoad{0%{left:-55%}100%{left:105%}}
@keyframes sqiFlash{0%,70%{opacity:0}75%{opacity:.16}100%{opacity:0}}
@keyframes sqiNoise{0%{transform:translate(0,0)}50%{transform:translate(4px,-3px)}100%{transform:translate(-3px,4px)}}



.app-modal{position:fixed;inset:0;background:rgba(5,5,5,.78);backdrop-filter:blur(8px);display:none;place-items:center;z-index:100;padding:16px}
.app-modal.open{display:grid}
.app-box{background:#fff;width:min(760px,100%);max-height:92vh;overflow:auto;border-radius:14px;border:1px solid #e4dbc8;box-shadow:0 30px 90px rgba(0,0,0,.25);padding:26px}
.app-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:20px}
.app-head h2{margin:0;font-size:25px;letter-spacing:-1px}
.app-head p{margin:7px 0 0;color:#777;font-size:12px;line-height:1.5}
.app-close{border:0;background:#f2f2f2;border-radius:50%;width:34px;height:34px;cursor:pointer;font-size:18px}
.app-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.app-field{display:flex;flex-direction:column;gap:6px}
.app-field.full{grid-column:1/-1}
.app-field label{font-size:9px;font-weight:950;letter-spacing:1.3px;color:#555}
.app-field input,.app-field select{width:100%;padding:12px;border:1px solid #ddd6c8;border-radius:7px;outline:none;font-size:13px;background:#fff}
.app-field input:focus,.app-field select:focus{border-color:#c89a22}
.app-actions{display:flex;gap:9px;justify-content:flex-end;margin-top:18px}
.app-msg{margin-top:10px;font-size:12px;font-weight:800}
.logo-preview{width:72px;height:72px;border:1px dashed #c9a227;border-radius:10px;display:grid;place-items:center;overflow:hidden;background:#faf9f4}
.logo-preview img{width:100%;height:100%;object-fit:contain}
.admin-shell{width:min(1050px,100%);max-height:94vh;overflow:auto;background:#f8f8f5;border-radius:14px}
.admin-top{background:#0a0a0a;color:#fff;padding:18px 22px;display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;z-index:5}
.admin-top b{letter-spacing:2px}.admin-top span{font-size:10px;color:#d9b34b}
.admin-body{padding:20px}
.admin-tabs{display:flex;gap:7px;overflow:auto;margin-bottom:16px}
.admin-tab{border:1px solid #ddd5c4;background:#fff;padding:10px 13px;border-radius:7px;font-size:9px;font-weight:950;white-space:nowrap;cursor:pointer}
.admin-tab.active{background:#c89a22;color:#fff;border-color:#c89a22}
.admin-card{background:#fff;border:1px solid #e5dfd2;border-radius:10px;padding:17px;margin-bottom:13px}
.admin-card h3{margin:0 0 13px;font-size:14px}
.admin-table{width:100%;border-collapse:collapse;font-size:11px}
.admin-table th,.admin-table td{border-bottom:1px solid #eee;padding:9px 7px;text-align:left;vertical-align:middle}
.admin-table th{font-size:8px;letter-spacing:1px;color:#777}
.admin-logo{width:38px;height:38px;object-fit:contain;border:1px solid #eee;border-radius:6px}
.pill{display:inline-block;padding:4px 7px;border-radius:20px;background:#f4f0e5;font-size:8px;font-weight:900}
.admin-actions{display:flex;gap:6px;flex-wrap:wrap}
.small-btn{border:1px solid #d7cfbe;background:#fff;padding:7px 9px;border-radius:6px;font-size:8px;font-weight:950;cursor:pointer}
.small-btn.gold{background:#c89a22;color:#fff;border-color:#c89a22}.small-btn.red{background:#191919;color:#fff;border-color:#191919}
.stat-admin{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.stat-admin div{background:#faf9f4;border:1px solid #e7dfcf;padding:15px;border-radius:8px}.stat-admin strong{display:block;font-size:23px}.stat-admin span{font-size:8px;letter-spacing:1px;color:#777}
@media(max-width:600px){.app-grid{grid-template-columns:1fr}.app-field.full{grid-column:auto}.stat-admin{grid-template-columns:1fr 1fr}.nav-inner>div:last-child{display:flex;gap:5px}.nav-cta{padding:8px 9px;font-size:8px}}
